import{_ as d,o as r,c as e,ag as o}from"./chunks/framework.C9sp7nFj.js";const _=JSON.parse('{"title":"CPOS","description":"","frontmatter":{},"headers":[],"relativePath":"2. 变量数据类型/2. 位置数据类型/CPOS.md","filePath":"2. 变量数据类型/2. 位置数据类型/CPOS.md","lastUpdated":1778862643000}'),a={name:"2. 变量数据类型/2. 位置数据类型/CPOS.md"};function l(c,t,n,s,i,P){return r(),e("div",null,[...t[0]||(t[0]=[o('<h1 id="cpos" tabindex="-1">CPOS <a class="header-anchor" href="#cpos" aria-label="Permalink to &quot;CPOS&quot;">​</a></h1><p>笛卡尔位置类型 - 这是基于<strong>直角坐标空间</strong>的数据类型。</p><p>存储 TCP 点在笛卡尔坐标系下位置。该变量可支持用户自主创建以及修改，也可在示教程序中进行赋值运算等操作。同时该变量支持在全局，工程，程序三大变量作用域中创建，删除，修改，复制，粘贴等操作（其中复制、粘贴操作不能跨域和跨工程）。</p><ul><li><strong>含义：</strong> 存储末端工具中心点（TCP）在笛卡尔坐标系（参考坐标系）下的位置。</li><li><strong>构成：</strong> * <strong>confdata (POSCFG 类型):</strong> 存储形态配置信息（见下文）。 <ul><li><strong>x, y, z:</strong> TCP 点在参考坐标系下的线性坐标。</li><li><strong>a, b, c:</strong> 欧拉角，定义 TCP 相对于参考坐标系的姿态。</li><li><strong>a7:</strong> 外部轴（如地轨）的坐标。</li></ul></li></ul><table tabindex="0"><thead><tr><th>参数</th><th>类型</th><th>说明</th><th>默认值/备注</th></tr></thead><tbody><tr><td><code>confdata</code></td><td>POSCFG</td><td>空间目标点对应的形态配置信息。</td><td>—</td></tr><tr><td><code>x</code></td><td>real</td><td>TCP 点在参考坐标系上 x 方向的坐标。</td><td>—</td></tr><tr><td><code>y</code></td><td>real</td><td>TCP 点在参考坐标系上 y 方向的坐标。</td><td>—</td></tr><tr><td><code>z</code></td><td>real</td><td>TCP 点在参考坐标系上 z 方向的坐标。</td><td>—</td></tr><tr><td><code>a</code></td><td>real</td><td>TCP 点相对于参考坐标系 z 轴旋转的欧拉角。</td><td>—</td></tr><tr><td><code>b</code></td><td>real</td><td>TCP 点相对于参考坐标系 y’轴旋转的欧拉角。</td><td>—</td></tr><tr><td><code>c</code></td><td>real</td><td>TCP 点相对于参考坐标系 x’’轴旋转的欧拉角。</td><td>—</td></tr><tr><td><code>a7</code></td><td>real</td><td>关节 7 号轴的坐标。</td><td>—</td></tr><tr><td><code>a16</code></td><td>real</td><td>关节 16 号轴的坐标。</td><td>机器人有几个轴就会显示几个轴的参数。</td></tr><tr><td><code>note</code></td><td>string</td><td>变量注释。</td><td>—</td></tr></tbody></table><ul><li>...：参数 a8~a15 的属性跟上述一样，都是 real 型变量，依次表示关节 8~关节 15 号轴的坐标值。</li></ul>',6)])])}const p=d(a,[["render",l]]);export{_ as __pageData,p as default};
